mapper.select:
SELECT `year_month`
FROM tbl_challenge_monthly_report
WHERE user_id = #{userId}
  AND `year_month` < #{currentYearMonth}
ORDER BY `year_month` DESC

SELECT DATE_FORMAT(MIN(assign_date), '%Y-%m')
FROM tbl_user_mission_info
WHERE user_id = #{userId}
  AND assign_date < #{currentMonthStart}

SELECT MIN(assign_date)
  FROM tbl_user_mission_info
 WHERE user_id = #{userId}
   AND assign_date <= #{endDate}

mapper.update:
UPDATE tbl_challenge_monthly_report
   SET group_record_json = CAST(#{groupRecordJson} AS JSON)
 WHERE user_id = #{userId}
   AND `year_month` = #{yearMonth}

mapper.select:
SELECT `year_month`, total_days, success_days, saved_amount, over_amount AS overspent_amount, net_amount,
       category_results_json AS category_effects_json, monthly_longest_streak, best_weekday, earned_score,
       weekly_results_json, difficulty_results_json, group_record_json
  FROM tbl_challenge_monthly_report
 WHERE user_id = #{userId}
   AND `year_month` = #{yearMonth}

SELECT EXISTS(
    SELECT 1
      FROM tbl_challenge_group g
      JOIN tbl_group_member member
        ON member.group_id = g.id
     WHERE member.user_id = #{userId}
       AND g.end_date BETWEEN #{startDate} AND #{endDate}
       AND g.status IN ('ACTIVE', 'JUDGING')
)
